function historyUpdateUI(){const h=state.history,undo=$('trozal3DUndo'),redo=$('trozal3DRedo'),count=$('trozal3DHistoryCount');if(undo)undo.disabled=!h.undo.length;if(redo)redo.disabled=!h.redo.length;if(count)count.textContent='Undo '+h.undo.length+' · Redo '+h.redo.length;}
