function historyRecord(label,key){const h=state.history;if(h.restoring)return;const current=historySnapshot();if(!h.last){h.last=current;historyUpdateUI();return;}if(current===h.last)return;const now=performance.now(),coalesceKey=key||label||'edit',coalesce=coalesceKey===h.lastKey&&now-h.lastAt<900;if(!coalesce){h.undo.push({snapshot:h.last,label:label||'Edit scene'});if(h.undo.length>h.limit)h.undo.shift();}h.redo=[];h.last=current;h.lastKey=coalesceKey;h.lastAt=now;historyUpdateUI();}
