const id=String(raw.id||'');if(!id||ids.has(id))throw new Error('Scene object IDs must be unique and non-empty.');ids.add(id);
const fields={};['x','y','z','rx','ry','rz'].forEach(k=>fields[k]=number(raw[k],0,-10000,10000));['sx','sy','sz'].forEach(k=>fields[k]=number(raw[k],1,.1,100));
