const cameraRaw=data.camera&&typeof data.camera==='object'?data.camera:{},target=Array.isArray(cameraRaw.target)&&cameraRaw.target.length===3?cameraRaw.target.map(v=>number(v,0,-10000,10000)):[0,.2,0];
const camera={yaw:number(cameraRaw.yaw,.72,-1000,1000),pitch:number(cameraRaw.pitch,.32,-1.55,1.55),distance:number(cameraRaw.distance,7.2,3,13),projection:cameraRaw.projection==='orthographic'?'orthographic':'perspective',orthoScale:number(cameraRaw.orthoScale,4.8,1,12),target};
