const bookmarks={A:null,B:null,C:null};['A','B','C'].forEach(slot=>{const v=data.cameraBookmarks&&data.cameraBookmarks[slot];if(v&&typeof v==='object'){const t=Array.isArray(v.target)&&v.target.length===3?v.target.map(n=>number(n,0,-10000,10000)):[0,.2,0];bookmarks[slot]={yaw:number(v.yaw,.72,-1000,1000),pitch:number(v.pitch,.32,-1.55,1.55),distance:number(v.distance,7.2,3,13),projection:v.projection==='orthographic'?'orthographic':'perspective',orthoScale:number(v.orthoScale,4.8,1,12),target:t};}});
