pause();state.objects=objects;state.selected=objects.some(o=>o.id===data.selected)?data.selected:objects[0].id;state.camera=camera;state.cameraBookmarks=bookmarks;state.lights=lights;state.duration=number(data.duration,8,1,120);state.fps=[24,30,60].includes(Number(data.fps))?Number(data.fps):30;state.loop=data.loop!==false;state.light=number(data.light,1.25,0,3);state.showGrid=data.showGrid!==false;state.transformSnap={enabled:snap.enabled===true,move:number(snap.move,.25,.01,10),rotate:number(snap.rotate,15,1,180),scale:number(snap.scale,.1,.01,2)};state.time=number(data.playhead,0,0,state.duration);
