async function importProjectFile(file){if(!file)return;try{const data=JSON.parse(await file.text());importProjectData(data);historyInitialize();}catch(error){say('Scene import failed: '+(error&&error.message?error.message:'invalid JSON'));}finally{$('trozal3DImportFile').value='';}}
function exportPng(){if(!state.gl){say('Snapshot PNG requires WebGL2.');return;}draw(state.time,true);$('trozal3DCanvas').toBlob(b=>{if(b){download(b,'trozal-canvas-3d-snapshot.png');say('PNG snapshot exported.');}else say('PNG export failed.');},'image/png');}
function preset(name){const a=defaults();if(name==='product'){a[0].name='Product Form';a[0].type='cylinder';a[0].x=0;a[1].name='Floating Cap';a[1].type='torus';a[1].x=0;a[1].y=1.05;a[2].name='Display Ground';a[2].type='plane';a[2].y=-.7;a[2].sx=2.8;a[2].sz=1.5;a[2].animation='none';}if(name==='abstract'){a[0].animation='bounce';a[1].animation='pulse';a[2].animation='orbit';}if(name==='orbit'){a[0].animation='spin';a[1].animation='orbit';a[2].animation='orbit';a[2].amount=1.1;}state.objects=a;state.selected=a[0].id;state.time=0;historyRecord('Apply scene preset','scene:preset:'+name);renderList();inspector();draw(0,true);say('Scene preset applied: '+name+'.');}
function clock(){const t=state.time;$('trozal3DClock').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+(t%60).toFixed(2).padStart(5,'0');$('trozal3DTime').value=String(t);}
function tick(now){if(!state.playing)return;const dt=Math.min(.05,Math.max(0,(now-state.lastFrame)/1000));state.lastFrame=now;state.time+=dt;if(state.time>=state.duration){if(state.loop)state.time%=state.duration;else{state.time=state.duration;pause();}}$('trozal3DTime').value=String(state.time);clock();draw(state.time,false);state.raf=requestAnimationFrame(tick);}
function play(){if(state.playing)return;if(state.time>=state.duration)state.time=0;state.playing=true;state.lastFrame=performance.now();$('trozal3DPlay').textContent='▶ Playing';state.raf=requestAnimationFrame(tick);}
function pause(){state.playing=false;cancelAnimationFrame(state.raf);if($('trozal3DPlay'))$('trozal3DPlay').textContent='▶ Play';}

function renderLights(){const host=$('trozal3DLightingControls');if(!host)return;host.replaceChildren();state.lights.slice(0,3).forEach((light,index)=>{const card=document.createElement('div');card.className='trozal3d-light-card';card.innerHTML='<strong></strong><label>Color <input type="color" data-light-index="'+index+'" data-light-field="color"></label><label>Intensity <output></output><input type="range" min="0" max="3" step="0.05" data-light-index="'+index+'" data-light-field="intensity"></label><div class="trozal3d-light-position">'+['x','y','z'].map(axis=>'<label>'+axis.toUpperCase()+' <input type="range" min="-6" max="6" step="0.1" data-light-index="'+index+'" data-light-field="'+axis+'"></label>').join('')+'</div>';card.querySelector('strong').textContent=(index+1)+' · '+light.name;card.querySelector('[data-light-field="color"]').value=light.color;const intensity=card.querySelector('[data-light-field="intensity"]');intensity.value=light.intensity;card.querySelector('output').textContent=light.intensity.toFixed(2);['x','y','z'].forEach(axis=>card.querySelector('[data-light-field="'+axis+'"]').value=light[axis]);host.appendChild(card);});}
