function setCameraView(view){state.camera.target=[0,.2,0];if(view==='front'){state.camera.yaw=0;state.camera.pitch=0;}else if(view==='side'){state.camera.yaw=Math.PI/2;state.camera.pitch=0;}else{state.camera.yaw=0;state.camera.pitch=1.48;}historyRecord('Set camera view','camera:view');draw(state.time,true);say('Camera view: '+view.toUpperCase()+'.');}
