$('trozal3DCameraBookmarkSave').addEventListener('click',()=>{const slot=$('trozal3DCameraBookmarkSlot').value;state.cameraBookmarks[slot]={...state.camera,target:[...state.camera.target]};historyRecord('Save camera bookmark','camera:bookmark:'+slot);say('Camera view '+slot+' saved to Scene JSON.');});
$('trozal3DCameraBookmarkRecall').addEventListener('click',()=>{const slot=$('trozal3DCameraBookmarkSlot').value,view=state.cameraBookmarks[slot];if(!view){say('Camera view '+slot+' is empty. Save a view first.');return;}state.camera={...view,target:[...view.target]};historyRecord('Recall camera bookmark','camera:bookmark:'+slot);$('trozal3DCameraProjection').value=state.camera.projection;$('trozal3DZoom').value=state.camera.distance;$('trozal3DOrthoScale').value=state.camera.orthoScale;outputs();draw(state.time,true);say('Camera view '+slot+' restored.');});
