$('trozal3DAdd').addEventListener('click',()=>{const type=$('trozal3DNewType').value,o={id:uid(),name:type[0].toUpperCase()+type.slice(1)+' '+(state.objects.length+1),type,x:0,y:0,z:0,rx:0,ry:0,rz:0,sx:1,sy:1,sz:1,color:'#55c9df',metallic:.25,roughness:.42,emission:0,materialPreset:'custom',animation:'spin',speed:.5,amount:.5,parentId:null,keyframes:[]};state.objects.push(o);state.selected=o.id;historyRecord('Add '+type,'objects:add');renderList();inspector();draw(state.time,true);say('Added '+o.name+'.');});
